-- 06_sostoyanie_izolyatsii - Таблицы
-- 06_sostoyanie_izolyatsii - 06_Состояние изоляции
drop table if exists "06_sostoyanie_izolyatsii";

create table "06_sostoyanie_izolyatsii" (
    id serial primary key,
    kod_k_izol int,                           -- Номер по порядку
    k_izol_min float,                         -- Минимальная поправка К к коэффициентам теплопроводности теплоизоляционных материалов
    k_izol_max float,                         -- Максимальная поправка К к коэффициентам теплопроводности теплоизоляционных материалов
    sosizol text ,                     -- Техническое состояние теплоизоляционной конструкции, условия эксплуатации -- 150
    name_sostizol text                  -- Краткое наименование -- 30
);

