    pr_year text ,                       -- Год постройки: С - до 1958г, Н - после 1958г, пробел - неизвестно -- 1
    q_ot float,                               -- Удельная тепловая характеристика для отопления
    q_vt float                                -- Удельная тепловая характеристика для вентиляции
);

