-- 13_klimaticheskie_dannye - Таблицы
-- 13_klimaticheskie_dannye - 13_Климатические данные
drop table if exists "13_klimaticheskie_dannye";

create table "13_klimaticheskie_dannye" (
    id serial primary key,
    sity text ,                        -- Город -- 255
    tag int,                                  -- Продолжительность отопительного периода, дня(ей)
    otopl_pr float,                           -- Расчетная температура наружного воздуха отопления, °C
    vetn_pr float,                            -- Расчетная температура наружного воздуха вентиляции, °C
    t_sr float,                               -- Средняя температура наружного воздуха отопительного периода, °C
    t_sr_min float,                           -- Средняя температура наружного воздуха самого холодного месяца, °C
    t_1month float,                           -- Январь
    t_2month float,                           -- Февраль
    t_3month float,                           -- Март
    t_4month float,                           -- Апрель
    t_5month float,                           -- Май
    t_6month float,                           -- Июгь
    t_7month float,                           -- Июль
    t_8month float,                           -- Август
    t_9month float,                           -- Сентябрь
    t_10month float,                          -- Октябрь
    t_11month float,                          -- Ноябрь
    t_12month float,                          -- Декабрь
    t_year float                              -- Среднегодовая
);

